@group(0) @binding(0) var<uniform> dims: Dims;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> dst: array<u32>;

@compute @workgroup_size(16, 16)
fn main(@builtin(global_invocation_id) id: vec3<u32>) {
  let x = id.x;
  let y = id.y;
  if (x >= dims.w || y >= dims.h) { return; }
  let xl = select(x - 1u, 0u, x == 0u);
  let xr = min(x + 1u, dims.w - 1u);
  let yu = select(y - 1u, 0u, y == 0u);
  let yd = min(y + 1u, dims.h - 1u);
  let s = 4u * src[y * dims.w + x]
        + src[y * dims.w + xl] + src[y * dims.w + xr]
        + src[yu * dims.w + x] + src[yd * dims.w + x];
  dst[y * dims.w + x] = s / 8u;
}
`;

async function main() {
  const path = Deno.args[0];
  const tokens = Deno.readTextFileSync(path).split(/\s+/).filter((t) => t.length > 0);
  const width = parseInt(tokens[0]);
  const height = parseInt(tokens[1]);
  const steps = parseInt(tokens[2]);
  const n = width * height;
  const data = new Uint32Array(n);
  for (let i = 0; i < n; i++) data[i] = parseInt(tokens[3 + i]) || 0;

  let result = data;
  if (steps > 0) {
    const adapter = await navigator.gpu.requestAdapter();
    if (!adapter) throw new Error("no WebGPU adapter");
    const device = await adapter.requestDevice();
    const bytes = n * 4;
    const usage = GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC | GPUBufferUsage.COPY_DST;
    const bufA = device.createBuffer({ size: bytes, usage });
    const bufB = device.createBuffer({ size: bytes, usage });
    const uni = device.createBuffer({
      size: 16,
      usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST,
    });
    const read = device.createBuffer({
      size: bytes,
      usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST,
    });
    device.queue.writeBuffer(bufA, 0, data);
    device.queue.writeBuffer(uni, 0, new Uint32Array([width, height, 0, 0]));

    const module = device.createShaderModule({ code: SHADER });
    const pipeline = device.createComputePipeline({
      layout: "auto",
      compute: { module, entryPoint: "main" },
    });
    const mk = (s: GPUBuffer, d: GPUBuffer) =>
      device.createBindGroup({
        layout: pipeline.getBindGroupLayout(0),
        entries: [
          { binding: 0, resource: { buffer: uni } },
          { binding: 1, resource: { buffer: s } },
          { binding: 2, resource: { buffer: d } },
        ],
      });
    const groups = [mk(bufA, bufB), mk(bufB, bufA)];
    const gx = Math.ceil(width / 16), gy = Math.ceil(height / 16);

    const enc = device.createCommandEncoder();
    for (let s = 0; s < steps; s++) {
      const pass = enc.beginComputePass();
      pass.setPipeline(pipeline);
      pass.setBindGroup(0, groups[s % 2]);
      pass.dispatchWorkgroups(gx, gy);
      pass.end();
    }
    enc.copyBufferToBuffer(steps % 2 === 0 ? bufA : bufB, 0, read, 0, bytes);
    device.queue.submit([enc.finish()]);
    await read.mapAsync(GPUMapMode.READ);
    result = new Uint32Array(read.getMappedRange().slice(0));
    read.unmap();
    device.destroy();
  }

  const lines: string[] = [];
  let sum = 0;
  for (let y = 0; y < height; y++) {
    const row: number[] = new Array(width);
    for (let x = 0; x < width; x++) {
      const v = result[y * width + x];
      row[x] = v;
      sum += v;
    }
    lines.push(row.join(" "));
  }
  lines.push(`SUM ${sum}`);
  Deno.stdout.writeSync(new TextEncoder().encode(lines.join("\n") + "\n"));
}

await main();
